COMMON=['4 menit: Periksa tujuan dan istilah.','10 menit: Baca materi, lalu susun kondisi dan dasar pengambilan keputusan.','7 menit: Tuliskan secara terpisah fakta dalam contoh dan hal yang belum dikonfirmasi.']
END='2 menit: Rangkum pokok pelajaran dan hal yang perlu dikonfirmasi di tempat kerja.'
AUTHORED={
50:dict(title='Membaca massa jenis relatif sebagai perbandingan dan membedakan satuannya',objective='Bedakan acuan massa jenis relatif dari satuan massa jenis, lalu bandingkan angka pada kondisi yang sama.',paragraphs=[
('Memeriksa zat pembanding','Massa jenis relatif adalah perbandingan terhadap massa jenis zat acuan. Dalam materi ini, acuan untuk benda padat dan cair adalah air pada 4°C dengan massa jenis relatif 1. Bedakan besaran ini dari massa jenis yang dinyatakan dengan satuan seperti g/cm³. Catatan dengan acuan atau suhu berbeda tidak boleh dianggap setara hanya karena angkanya mirip.'),
('Menghitung perbandingan untuk volume yang sama','Dalam contoh di atas kertas, massa sampel dan air acuan yang volumenya sama ditetapkan masing-masing 84 g dan 30 g. Perbandingannya adalah 84÷30=2.8. Ini berbeda dari langsung membagi dua massa yang volumenya tidak sama. Angka ini hanya untuk belajar, bukan hasil pengujian untuk mengesahkan jenis material di tempat kerja.'),
('Menyalin angka dari tabel material','Contoh logam dalam sumber mencantumkan aluminium 2.68 dan besi 7.87. Karena paduan dan kondisi dapat menyebabkan perbedaan, jangan menggantinya dengan angka massa jenis dari sumber lain tanpa persetujuan. Saat membahas pengurangan massa komponen, periksa juga kekuatan, bentuk, suhu, dan persetujuan material yang disyaratkan; jangan mempertimbangkan massa jenis relatif saja.')],terms=['Perbandingan massa jenis terhadap massa jenis zat acuan.','Zat yang dijadikan dasar perbandingan.','Tidak memiliki satuan karena merupakan perbandingan besaran sejenis.','Memiliki volume yang sama.'],activity='7 menit: Hitung perbandingan dari dua pasangan massa yang bervolume sama, lalu pisahkan kolom catatan massa jenis, massa jenis relatif, dan suhu acuan.',safety=['Jangan memutuskan bahwa material yang jenisnya belum jelas adalah material yang ditentukan hanya berdasarkan massa jenis relatif, lalu mulai mengerjakannya.'],summary='Massa jenis relatif adalah perbandingan yang memiliki acuan. Bedakan dari satuan massa jenis dan bandingkan pada kondisi yang sama.'),
51:dict(title='Memilih cara menempatkan mistar baja dan busur derajat',objective='Bedakan objek pengukuran panjang dan sudut, lalu periksa permukaan ujung, permukaan acuan, dan arah pembacaan.',paragraphs=[
('Membaca panjang dengan mistar baja','Mistar baja digunakan untuk mengukur panjang. Sejajarkan ujung objek dengan posisi acuan dan baca skala dari arah depan. Periksa apakah ujung mistar rusak atau skalanya kotor. Jangan menganggap alat ini dapat menjamin toleransi presisi seolah-olah cukup menggunakannya seperti penggaris kertas. Pilih alat yang ditetapkan dalam persyaratan.'),
('Sudut menyatakan hubungan dua permukaan','Busur derajat umumnya menggabungkan pelat berskala sudut dan bilah. Tempatkan bidang dasar dan bilah pada dua permukaan datar yang ingin diukur, lalu baca skalanya. Jika salah satunya terangkat atau menyentuh permukaan yang berbeda, angka yang terbaca bukan sudut yang dimaksud.'),
('Berkonsultasi tentang pemilihan alat','Bedakan permintaan untuk mengetahui panjang ujung dari permintaan untuk mengetahui sudut permukaan miring. Jika dua permukaan acuan belum jelas, tunjukkan gambar teknik dan tanyakan; jangan menggantinya sendiri dengan permukaan yang lebih mudah dilihat. Catat nama alat, objek, permukaan kontak, dan satuannya.')],terms=['Alat untuk membaca panjang melalui skala.','Bagian yang memiliki skala sudut.','Bagian berbentuk batang yang ditempatkan pada permukaan yang diukur.','Permukaan tempat alat dan objek saling bersentuhan.'],activity='7 menit: Gambarkan satu pengukuran panjang dan satu pengukuran sudut. Gunakan warna berbeda untuk acuan dan dua permukaan kontak.',safety=['Jangan menempelkan alat pada komponen yang bergerak. Waspadai tepi tajam dan ikuti prosedur pengukuran yang ditetapkan.'],summary='Selain memastikan skala dapat dibaca, periksa objek dan penempatan kontak yang benar.'),
52:dict(title='Membedakan acuan alat ukur tinggi dan alat ukur kedalaman',objective='Jelaskan permukaan acuan, arah gerak, dan nilai pembacaan untuk pengukuran tinggi dan kedalaman.',paragraphs=[
('Acuan tinggi adalah meja rata','Alat ukur tinggi digunakan di atas meja rata untuk mengukur tinggi dan besaran lain dari permukaan meja tersebut. Pastikan ujung ukur bergerak tegak lurus terhadap permukaan acuan serta tidak ada benda asing pada dasar alat atau meja rata. Jangan menganggap meja yang miring sebagai acuan yang setara.'),
('Kedalaman diukur dari permukaan atas','Alat ukur kedalaman mengukur kedalaman dari permukaan yang dijadikan acuan. Tempatkan alat dengan stabil pada permukaan acuan dan pastikan permukaan ukurnya mencapai objek dengan benar. Jika ujung ukur tidak mencapai dasar alur, jangan mencatat nilai yang disesuaikan agar cocok dengan kedalaman pada gambar teknik.'),
('Memeriksa nilai pembacaan setiap alat','Tersedia tampilan analog dan digital. Contoh tipe nonius dalam materi menunjukkan nilai pembacaan 0.05 mm atau 0.02 mm. Tidak semua alat memiliki spesifikasi yang sama. Sebelum membandingkan, samakan pemeriksaan spesifikasi alat, nol atau titik acuan, lokasi pengukuran, dan kondisi suhu.')],terms=['Alat untuk mengukur tinggi dan besaran lain dari permukaan meja rata.','Alat untuk mengukur kedalaman dari permukaan acuan.','Meja datar yang menjadi acuan pengukuran dan pekerjaan sejenis.','Titik yang dijadikan dasar pengaturan nilai.'],activity='7 menit: Tunjukkan secara terpisah permukaan acuan untuk tinggi komponen bertingkat dan kedalaman lubang, lalu buat contoh catatan yang belum dikonfirmasi.',safety=['Jangan memaksa ujung ukur masuk. Lindungi permukaan presisi dan ikuti prosedur yang ditetapkan untuk alat.'],summary='Tinggi dan kedalaman memiliki permukaan acuan yang berbeda. Catat spesifikasi dan kontak alat masing-masing.'),
53:dict(title='Memeriksa pembagian tanggung jawab keselamatan dan komunikasi sehari-hari',objective='Kenali sistem keselamatan dan kesehatan perusahaan serta pihak yang perlu dihubungi pekerja, lalu bedakan sapaan dari laporan bahaya.',paragraphs=[
('Tidak menyerahkan semuanya kepada satu orang','Penjelasan keselamatan dan kesehatan kerja dalam sumber menunjukkan tiga unsur: standar pencegahan bahaya, sistem tanggung jawab, dan kegiatan mandiri. Perusahaan dan pekerja sama-sama memiliki peran. Bahaya tidak hilang hanya karena nama penanggung jawab telah ditetapkan. Pastikan pihak yang dapat dimintai saran dan jalur komunikasi darurat.'),
('Mengenali peran khusus','Komite keselamatan dan kesehatan membahas masalah keselamatan dan kesehatan. Pengelola keselamatan, dokter perusahaan, dan pihak lain menjalankan peran khusus. Konfirmasikan persyaratan pembentukan dan penunjukan yang berlaku di tempat kerja; jangan menetapkan penerapan hukum hanya berdasarkan pelajaran ini. Arahkan konsultasi kesehatan ke saluran yang ditetapkan.'),
('Sapaan dan laporan memiliki tujuan berbeda','Sapaan pagi dan ungkapan seperti “utamakan keselamatan” membantu membangun hubungan kerja sama. Namun, mengangguk saja bukan laporan tentang ketidaknormalan mesin. Jika ada ketidaknormalan, sampaikan dengan jelas objek, fakta, dan tindakan yang telah dilakukan, lalu pastikan lawan bicara memahaminya.')],terms=['Sistem yang memperjelas peran serta hubungan komunikasi dan pengambilan keputusan.','Dokter khusus yang mendukung kesehatan orang yang bekerja di perusahaan.','Pihak yang menerima konsultasi atau komunikasi.','Menyampaikan kata-kata kepada orang lain untuk mengingatkan atau mengajak bekerja sama.'],activity='7 menit: Gambarkan bagan komunikasi tempat kerja rekaan. Hubungkan sapaan, laporan ketidaknormalan, dan konsultasi kesehatan dengan pihak yang sesuai.',safety=['Jangan menetapkan persyaratan penunjukan atau penerapan hukum hanya dari penjelasan umum materi. Konfirmasikan kepada penanggung jawab.'],summary='Keselamatan didukung oleh sistem dan tindakan sehari-hari. Sapaan tidak menggantikan laporan.'),
54:dict(title='Memeriksa jenis pelatihan dan batas pekerjaan yang boleh dilakukan',objective='Bedakan pelatihan saat mulai bekerja atau berganti tugas dari pemeriksaan kualifikasi dan pelatihan yang diperlukan untuk pekerjaan berbahaya.',paragraphs=[
('Pekerjaan berubah, pemeriksaan juga berubah','Saat mulai bekerja atau beralih ke tugas baru, pelajari bahaya mesin dan bahan baku, alat pelindung, perangkat keselamatan, prosedur, pemeriksaan sebelum bekerja, penataan dan kebersihan, serta evakuasi saat kecelakaan. Kemampuan mengoperasikan mesin sebelumnya tidak berarti peralatan baru dapat dioperasikan dengan kondisi yang sama.'),
('Tidak menyamakan semua kualifikasi dan pelatihan','Untuk forklift, pengaturan dan pemeliharaan robot, pemasangan perlengkapan pengangkatan, dan pekerjaan lain, perlu diperiksa kualifikasi atau pelatihan yang sesuai dengan objek dan kondisinya. Jangan menyatakan bahwa satu kursus memenuhi semuanya. Tanyakan kepada penanggung jawab tentang persyaratan yang sesuai dengan jenis pekerjaan dan kondisi peralatan. Menyelesaikan materi atau lulus simulasi ujian tidak menggantikan izin kerja di lapangan.'),
('Mencocokkan catatan dengan lingkup pelaksanaan','Pastikan nama pelatihan, peralatan yang menjadi objeknya, lingkup pekerjaan, dan pihak yang mengonfirmasi. Jika telah diajari pengoperasian tetapi belum diajari penyetelan internal, jangan mulai menyetel hanya karena mesinnya sama. Menghentikan pekerjaan yang belum jelas dan meminta saran juga merupakan tindakan untuk belajar dengan aman.')],terms=['Pelatihan keselamatan dan kesehatan yang diperlukan saat mulai bekerja.','Perubahan tugas atau kondisi pekerjaan yang ditangani.','Kategori pelatihan untuk pekerjaan berbahaya atau merugikan kesehatan yang telah ditetapkan.','Lingkup pekerjaan yang telah diizinkan dan boleh dilaksanakan.'],activity='7 menit: Bayangkan pemindahan tugas ke mesin baru. Buat tabel yang membedakan bagian yang sudah dipelajari, yang belum dikonfirmasi, dan lingkup yang diizinkan.',safety=['Jangan memulai sendiri pekerjaan jika kualifikasi, pelatihan, dan izin yang diperlukan belum dapat dikonfirmasi.'],summary='Periksa jenis, objek, dan lingkup pelatihan. Materi belajar berbeda dari izin melakukan pekerjaan di lapangan.'),
55:dict(title='Tidak berhenti pada menghitung kejadian nyaris celaka',objective='Bedakan makna pembelajaran rasio Heinrich dari pelaporan fakta dan pemeriksaan tindakan pencegahan.',paragraphs=[
('Tetap ada informasi meskipun tidak terluka','Kejadian nyaris celaka adalah kejadian ketika bahaya disadari meskipun tidak sampai menjadi kecelakaan. Misalnya, benda hampir jatuh atau kaki hampir terpeleset. Mencatat lokasi, gerakan, dan kondisi sekitar selain hasil akhirnya membantu penyelidikan penyebab. Jangan mengabaikan pencatatan hanya karena tidak ada cedera.'),
('Rasio bukan angka masa depan yang pasti','Sumber menyajikan gagasan Heinrich sebagai 1 kecelakaan berat, 29 kecelakaan ringan, dan 300 kejadian nyaris celaka. Rasio ini digunakan untuk belajar agar tanda kecil tidak terlewat, bukan rumus prediksi bahwa setiap tempat kerja pasti mengalami jumlah yang sama. Pertimbangkan juga tingkat keparahan saat menanggapi.'),
('Melanjutkan laporan hingga pemeriksaan tindakan','Roda troli berhenti pada perbedaan ketinggian lantai dan muatannya miring. Laporkan waktu kejadian, lokasi perbedaan ketinggian, cara penumpukan, dan tindakan menghindar yang dilakukan. Bagikan siapa yang akan memeriksa tindakan apa. Jangan menganggap pencegahan selesai hanya karena jumlah kejadian telah dihitung. Setelah tindakan dilakukan, periksa apakah masalah yang sama atau bahaya lain masih ada.')],terms=['Kejadian yang menimbulkan kesadaran akan bahaya meskipun tidak menjadi kecelakaan.','Perubahan yang menunjukkan kemungkinan adanya masalah.','Tingkat keparahan yang relatif kecil.','Terjadinya kembali masalah yang serupa.'],activity='7 menit: Untuk kejadian rekaan tanpa cedera, catat secara terpisah fakta, dugaan penyebab, tindakan pencegahan, dan penanggung jawab pemeriksaannya.',safety=['Jangan benar-benar memperagakan ulang situasi berbahaya untuk membuat bahan laporan.'],summary='Jangan menganggap rasio sebagai prediksi yang pasti terjadi. Gunakan untuk melaporkan tanda bahaya dan memeriksa tindakan pencegahan.'),
56:dict(title='Membedakan bahaya muatan tergantung dan perkakas pengencang',objective='Jelaskan bahaya jatuhnya muatan, pengaruh sudut tali kawat, dan risiko memaksa baut masuk.',paragraphs=[
('Tidak masuk ke bawah muatan tergantung','Muatan pada derek dapat jatuh akibat masalah tali kawat atau pemasangannya. Jangan berada di bawah muatan atau memasuki daerah bahaya yang ditentukan; patuhi pengendalian akses dan isyarat. Untuk pemasangan perlengkapan pengangkatan atau pengoperasian, periksa kualifikasi, pelatihan, dan lingkup tugas yang diperlukan. Orang yang kebetulan berada di dekatnya tidak boleh mulai membantu atas keputusan sendiri.'),
('Sudut mengubah beban pada tali','Ketika sudut bukaan tali kawat bertambah besar, gaya pada tali dapat bertambah meskipun muatannya sama. Jangan menentukan sudut aman atau cara pengangkatan hanya berdasarkan penampilan. Periksa ketentuan untuk muatan, perlengkapan, dan rencana pengangkatan. Jangan menghitung sendiri kapasitas angkat peralatan nyata dari penjelasan materi lalu mengubahnya.'),
('Tidak memukul baut yang sulit masuk','Sebelum menggunakan kunci impak, pastikan ulir dan komponen cocok. Jika baut sulit masuk, memukul kepalanya dengan palu dapat merusak ulir. Jangan memaksa pengencangan. Sesuai prosedur, mintalah pemeriksaan nomor komponen, posisi, benda asing, dan kerusakan.')],terms=['Muatan yang diangkat dengan derek atau alat sejenis.','Pekerjaan memasang atau melepas perlengkapan untuk menggantung dan mengangkat muatan.','Bagian spiral pada ulir yang saling berkaitan.','Perkakas yang menggunakan mekanisme tumbukan untuk pengencangan dan pekerjaan sejenis.'],activity='7 menit: Buat secara terpisah rencana daerah larangan masuk di sekitar muatan tergantung dan permintaan pemeriksaan baut yang sulit masuk.',safety=['Jangan mendekati muatan tergantung untuk menahannya dengan tangan. Jangan mengubah cara pengangkatan atau kondisi pengencangan tanpa persetujuan.'],summary='Periksa muatan tergantung, sudut tali, dan ketidakcocokan ulir sebagai bahaya yang berbeda.')
}
